. (Join-Path $PSScriptRoot 'Common.ps1')
. (Join-Path $PSScriptRoot 'Raw.ps1')
$taskRoot='E:\PRACA AI CAŁY FOLDER\INNER DOJO\Working\2026-10-24\NOOB_LONEWOLF_DOJO_PACKAGE';$mods=Join-Path $taskRoot 'build_v2\mods'
$source='E:\PRACA AI CAŁY FOLDER\SEKIRO\VANILLA_WORKFILES_BASE\LMTSR_Lone_Wolf_Master_Hardcore_V1.0';$rel='param\gameparam\gameparam.parambnd.dcx'
$out=[SoulsFormats.BND4]::Read((Raw (Join-Path $mods $rel)));$src=[SoulsFormats.BND4]::Read((Raw (Join-Path $source $rel)));$plan=Get-Content -LiteralPath (Join-Path $taskRoot 'reports\AUTHOR_LONEWOLF_DELTA.json') -Raw|ConvertFrom-Json
$defByType=@{};foreach($df in Get-ChildItem -LiteralPath $defs -Filter '*.xml'){$xml=[xml](Get-Content -LiteralPath $df.FullName -Raw);$defByType[[string]$xml.PARAMDEF.ParamType]=$df.BaseName}
$cache=@{};$sourceCache=@{};$metaCache=@{}
function Rows($binder,[string]$name,$cache){if($cache.ContainsKey($name)){return $cache[$name]};$files=@($binder.Files|Where-Object {[IO.Path]::GetFileName($_.Name) -ceq ($name+'.param')});if($files.Count -ne 1){return $null};$table=[SoulsFormats.PARAM]::Read($files[0].Bytes);$def=$defByType[[string]$table.ParamType];Need ($null -ne $def) "Missing def $name";$table.ApplyParamdef([SoulsFormats.PARAMDEF]::XmlDeserialize((Join-Path $defs ($def+'.xml')),$false));$map=@{};foreach($r in $table.Rows){if(-not $map.ContainsKey($r.ID)){$map[$r.ID]=$r}};$obj=@{table=$table;rows=$map;def=$def};$cache[$name]=$obj;return $obj}
function Meta($name){$data=Rows $out $name $cache;if($null -eq $data){return $null};if($metaCache.ContainsKey($name)){return $metaCache[$name]};$path=Join-Path (Split-Path $defs -Parent) ('Meta\'+$data.def+'.xml');if(-not(Test-Path -LiteralPath $path)){return $null};$xml=[xml](Get-Content -LiteralPath $path -Raw);$metaCache[$name]=$xml;return $xml}
$queue=[Collections.Generic.Queue[object]]::new();foreach($r in $plan.changes){$queue.Enqueue(@{table=$r.table;id=[int]$r.id})};$seen=@{};$missing=@();$unsupported=@();$edges=0
while($queue.Count){$item=$queue.Dequeue();$key=$item.table+'/'+$item.id;if($seen.ContainsKey($key)){continue};$seen[$key]=$true;Need ($seen.Count -lt 20000) 'Reference traversal unexpectedly large';$data=Rows $out $item.table $cache;$row=$data.rows[$item.id];if($null -eq $row){continue};$meta=Meta $item.table;if($null -eq $meta){continue};$cells=@{};foreach($c in $row.Cells){$cells[$c.Def.InternalName]=$c.Value}
 foreach($node in $meta.PARAMMETA.Field.ChildNodes){if($node.NodeType -ne 'Element' -or -not $node.HasAttribute('Refs')){continue};$field=$node.LocalName;if(-not $cells.ContainsKey($field)){continue};$id=[long]$cells[$field];if($id -le 0 -or $id -gt [int]::MaxValue){continue};if($item.table -eq 'SpEffectParam' -and $field -eq 'behaviorId' -and $cells['stateInfo'] -ne 275){continue};$targets=@();foreach($expr in $node.Refs.Split(',')){if($expr -match '^([A-Za-z0-9_]+)(?:\(([A-Za-z0-9_]+)=(-?\d+)\))?$'){$target=$matches[1];if($matches[2] -and $cells[$matches[2]] -ne [int]$matches[3]){continue};if($item.table -eq 'BehaviorParam_PC' -and $field -eq 'refId' -and $target -eq 'AtkParam_Npc'){continue};if($item.table -eq 'BehaviorParam' -and $field -eq 'refId' -and $target -eq 'AtkParam_Pc'){continue};$targets+=$target}else{$unsupported+=@{table=$item.table;field=$field;expression=$expr}}}
  $existing=@();$sourceExists=@();foreach($target in $targets){$tr=Rows $out $target $cache;if($null -ne $tr -and $tr.rows.ContainsKey([int]$id)){$existing+=$target};$sr=Rows $src $target $sourceCache;if($null -ne $sr -and $sr.rows.ContainsKey([int]$id)){$sourceExists+=$target}}
  $edges++;if($existing.Count){foreach($target in $existing){$queue.Enqueue(@{table=$target;id=[int]$id})}}elseif($targets.Count){$missing+=@{fromTable=$item.table;fromID=$item.id;field=$field;targetTables=$targets;targetID=$id;presentInAuthor=$sourceExists}}
 }
}
Json-Write @{scope='Conditional Paramdex Meta Refs from all authored changed/new rows and their reachable parameter references; positive IDs only, recognized simple conditions; no TAE/HKS/runtime reachability proof';rowsVisited=$seen.Count;edges=$edges;missing=$missing;unsupported=$unsupported} (Join-Path $taskRoot 'reports\PARAM_REFERENCE_AUDIT.json')
'PARAM_REFERENCES_AUDITED'
